private fun moreSpecs(title: String, en: Boolean): List<MoreSpec> = when(title) {
    "Phishing", "Smishing", "Vishing", "Coduri QR frauduloase" -> if(en) listOf(m12EN,m13EN) else listOf(m12RO,m13RO)
    "Deepfake" -> listOf(if(en) m14EN else m14RO)
    "Wi-Fi" -> listOf(if(en) m15EN else m15RO)
    "Date mobile" -> listOf(if(en) m17EN else m17RO)
    "Canale de notificări" -> listOf(if(en) m18EN else m18RO)
    "Actualizări de securitate" -> listOf(if(en) m20EN else m20RO)
    else -> emptyList()
}

@Composable
internal fun FoniWiseMoreVisuals(title: String, english: Boolean, advanced: Boolean) {
    moreSpecs(title, english).forEach { spec ->
        key(spec.id, title, english, advanced) { MoreVisual(spec, english, advanced) }
    }
}

private fun Element.elements(): List<Element> = listOf(this) + (0 until childNodes.length).flatMap {
    (childNodes.item(it) as? Element)?.elements() ?: emptyList()
}
private fun Element.id(id: String) = elements().firstOrNull { it.getAttribute("id") == id }
private fun Element.set(id: String, attr: String, value: String) { this.id(id)?.setAttribute(attr,value) }
private fun Element.show(id: String, visible: Boolean) = set(id,"visibility",if(visible) "visible" else "hidden")

@Composable
private fun NativeDiagram(xml: String, description: String, expanded: Boolean, state: Any, change: (Element)->Unit = {}) {
    val context=LocalContext.current
    val font=remember(context) { context.resources.getFont(R.font.nunito_sans) }
    val root=remember(xml,state) {
        DocumentBuilderFactory.newInstance().apply { isExpandEntityReferences=false }
            .newDocumentBuilder().parse(xml.byteInputStream(Charsets.UTF_8)).documentElement.apply(change)
    }
    val view=remember(root) { root.getAttribute("viewBox").trim().split(Regex("[ ,]+")).map { it.toFloat() } }
    BoxWithConstraints(Modifier.fillMaxWidth()) {
        val diagramWidth=if(expanded) maxOf(maxWidth,420.dp) else maxWidth
        val scroll=key(expanded) { rememberScrollState() }
        Box(if(expanded) Modifier.fillMaxWidth().horizontalScroll(scroll) else Modifier.fillMaxWidth()) {
            Canvas(Modifier.width(diagramWidth).aspectRatio(view[2]/view[3]).semantics { contentDescription=description }) {
                drawIntoCanvas {
                    val canvas=it.nativeCanvas
                    val save=canvas.save()
                    canvas.clipRect(0f,0f,size.width,size.height)
                    canvas.scale(size.width/view[2],size.height/view[3])
                    canvas.translate(-view[0],-view[1])
                    drawFoniWiseStaticSvg(canvas,root,font)
                    canvas.restoreToCount(save)
                }
            }
        }
    }
}
@Composable
private fun Pick(items: List<String>, value: Int, onPick: (Int)->Unit) {
    items.forEachIndexed { index,label ->
        FilterChip(selected=value==index,onClick={onPick(index)},label={Text(label,color=dark)},
            colors=FilterChipDefaults.filterChipColors(containerColor=pale,selectedContainerColor=lime),
            modifier=Modifier.fillMaxWidth().heightIn(min=48.dp))
    }
}
@Composable
private fun Toggle(label: String, value: Boolean, change: (Boolean)->Unit) {
    Row(Modifier.fillMaxWidth().heightIn(min=48.dp),verticalAlignment=Alignment.CenterVertically) {
        Text(label,Modifier.weight(1f),color=dark)
        Switch(checked=value,onCheckedChange=change,modifier=Modifier.semantics { contentDescription=label })
    }
}
@Composable
private fun Range(label: String, value: Int, min: Int,max: Int,onChange:(Int)->Unit) {
    Text(label,color=dark,fontWeight=FontWeight.Bold)
    Slider(value=value.toFloat(),onValueChange={onChange(it.roundToInt().coerceIn(min,max))},
        valueRange=min.toFloat()..max.toFloat(),steps=max-min-1,
        modifier=Modifier.fillMaxWidth().heightIn(min=48.dp).semantics { contentDescription=label })
}
@Composable
private fun Result(text: String, warning: Boolean=false) {
    if(text.isNotEmpty()) Surface(color=if(warning) Color(0xFFFBEDE7) else pale,shape=RoundedCornerShape(8.dp),
        modifier=Modifier.fillMaxWidth().semantics { liveRegion=LiveRegionMode.Polite }) {
        Text(text,color=dark,modifier=Modifier.padding(12.dp))
    }
}
@Composable
private fun Grid(count: Int, accent: Color, desc: String) {
    Canvas(Modifier.fillMaxWidth().height(138.dp).semantics { contentDescription=desc }) {
        val gap=2.dp.toPx();val w=(size.width-9*gap)/10;val h=(size.height-9*gap)/10
        repeat(100) { i -> drawRoundRect(if(i<count) accent else soft,
            topLeft=androidx.compose.ui.geometry.Offset((i%10)*(w+gap),(i/10)*(h+gap)),
            size=androidx.compose.ui.geometry.Size(w,h),cornerRadius=androidx.compose.ui.geometry.CornerRadius(1.dp.toPx())) }
    }
}

@Composable
private fun MoreVisual(s: MoreSpec,en:Boolean,advanced:Boolean) {
    fun tr(ro:String,eng:String)=if(en) eng else ro
    var part by rememberSaveable { mutableIntStateOf(-1) }
    var mode by rememberSaveable { mutableIntStateOf(if(advanced && s.id in listOf(18,20)) 1 else 0) }
    var second by rememberSaveable { mutableIntStateOf(if(s.id==14) 90 else if(s.id==17) 10 else 0) }
    var number by rememberSaveable { mutableIntStateOf(5) }
    var a by rememberSaveable { mutableStateOf(s.id==15) }
    var zoom by rememberSaveable { mutableStateOf(false) }
    val fmt=remember(en){ NumberFormat.getNumberInstance(if(en) Locale.US else Locale.forLanguageTag("ro-RO")).apply { maximumFractionDigits=2 } }
    val detail=s.details.getOrNull(if(s.id in listOf(18,20)) mode else 0)?.getOrNull(part)
        ?:s.initial.getOrNull(if(s.id in listOf(18,20)) mode else 0).orEmpty()
    Surface(color=background,shape=RoundedCornerShape(12.dp),modifier=Modifier.fillMaxWidth()) {
        Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)) {
            Surface(color=dark,shape=RoundedCornerShape(8.dp),modifier=Modifier.fillMaxWidth()) {
                Text(s.title,color=Color.White,fontWeight=FontWeight.Bold,modifier=Modifier.padding(12.dp))
            }
            if(s.id==12) {
                Text(tr("Schema completă este afișată inițial. Mărește schema pentru a citi etichetele, apoi derulează orizontal.","The full diagram is shown first. Enlarge it to read the labels, then scroll horizontally."),color=dark)
                Toggle(tr("Mărește schema","Enlarge diagram"),zoom){zoom=it}
            }
            when(s.id) {
                12 -> {
                    NativeDiagram(s.svg[0],s.title,zoom,part){root->root.elements().filter{it.tagName=="rect"}.drop(1).forEachIndexed{i,e->
                        e.setAttribute("stroke",if(i==part) "#064D2B" else if(i==0) "none" else "#087C26");e.setAttribute("stroke-width",if(i==part) "3" else "1")
                    }}
                    Pick(s.choices[0],part){part=it};Result(detail)
                }
                13 -> {
                    NativeDiagram(s.svg[part+1],tr("Două pagini fictive cu aspect identic și domenii diferite","Two fictional pages with identical appearance and different domains"),false,part)
                    Pick(s.choices[0],part){part=it};Result(detail)
                }
                14 -> {
                    Text(s.extra[2],color=dark)
                    Grid(number,coral,s.extra[0]+": "+number)
                    Range(s.extra[0]+": "+number,number,0,100){number=it}
                    Grid(second,green,s.extra[1]+": "+second)
                    Range(s.extra[1]+": "+second,second,0,100){second=it}
                    Result(if(en) "False alarms: $number; correctly detected: $second; missed: ${100-second}" else "Alarme false: $number; detectate corect: $second; nedetectate: ${100-second}")
                }
                15 -> {
                    NativeDiagram(s.svg[0],s.title,false,a){root->root.set("uplink","stroke",if(a) "#087C26" else "#C96846");root.show("broken",!a)}
                    Toggle(s.extra[0],a){a=it}
                    val status=if(en) "Wi-Fi active; internet "+(if(a) "available" else "unavailable") else "Wi-Fi activ; internet "+(if(a) "disponibil" else "indisponibil")
                    Result(status,!a)
                }
                17 -> {
                    val volume=number*second*60/8.0
                    Range(tr("Viteza: ","Speed: ")+number+" Mb/s",number,1,20){number=it}
                    val unit=if(en) if(second==1) "minute" else "minutes" else if(second==1) "minut" else if(second>=20) "de minute" else "minute"
                    Range(tr("Durata: ","Duration: ")+second+" "+unit,second,1,60){second=it}
                    Result(tr("Volum: ","Volume: ")+fmt.format(volume)+" MB")
                    Box(Modifier.fillMaxWidth().height(16.dp).background(pale,RoundedCornerShape(8.dp))) {
                        Box(Modifier.fillMaxWidth((volume/9000).toFloat()).fillMaxHeight().background(green,RoundedCornerShape(8.dp)))
                    }
                }
                18,20 -> {
                    Pick(s.modes,mode){mode=it;part=-1}
                    NativeDiagram(s.svg[mode],s.title,false,listOf(mode,part)){root->
                        root.elements().filter{it.tagName=="g"&&it.getAttribute("id").startsWith("v"+s.id)}.forEachIndexed{i,e->e.setAttribute("visibility",if(i==part) "visible" else "hidden")}
                    }
                    Pick(s.choices[mode],part){part=it};Result(detail)
                }
            }
            if(s.note.isNotBlank()) Text(s.note,color=dark,style=MaterialTheme.typography.bodySmall)
            Text(tr("Exemplu informativ","Illustrative example"),color=dark,style=MaterialTheme.typography.labelMedium)
            OutlinedButton(onClick={
                part=-1;mode=0;second=if(s.id==14) 90 else if(s.id==17) 10 else 0
                number=5;a=s.id==15;zoom=false
            },modifier=Modifier.fillMaxWidth().heightIn(min=48.dp)){Text(tr("Revino la exemplul inițial","Reset example"),color=dark)}
        }
    }
}
